<script>document.addEventListener('DOMContentLoaded',function(){const mode=document.getElementById('population-mode'),box=document.getElementById('population-manual');if(!mode||!box)return;function update(){box.hidden=mode.value!=='manual';box.querySelectorAll('input').forEach(function(input){input.disabled=box.hidden;input.required=!box.hidden;});}mode.addEventListener('change',update);update();});</script>
